sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	var identifier = current.variables.order_guide_identifier;

    if (gs.nil(identifier) || gs.nil(current.request)) {
        return;
    }

    var req = new GlideRecord('sc_request');

    if (req.get(current.request)) {

        if (gs.nil(req.x_1956466_projec_0_order_guide_identifier)) {

            req.x_1956466_projec_0_order_guide_identifier = identifier;
            req.update();

        }
    }

})(current, previous);
